<script setup lang="ts">
import { nextTick, onUnmounted, ref } from 'vue'
import { ICON_CODES } from '../../actions/uiactiondata'
import { inspectorArrangeChanges, inspectorPropertyChanges, inspectorPropertyResets, type InspectorModelInfo, type InspectorValue, type InspectorArrangeCommand } from '../../../src/index'
import { qtrc, useLanguage } from '../../i18n'
useLanguage()
import { currentScore } from '../../scoreview'
import { applyInspectorChanges, scoreChanged } from '../editbridge'
import InspectorSpin from './InspectorSpin.vue'

const props = defineProps<{ model: InspectorModelInfo; section: string; path: string[]; showMoreOnly?: boolean; chord?: InspectorModelInfo }>()
const headExpanded = ref(false)
const dynamicExpanded = ref(false)
const appearanceOpen = ref(false)
const appearanceButton = ref<HTMLButtonElement | null>(null)
const appearanceContainer = ref<HTMLElement | null>(null)
function closeAppearance(restore = false) {
  appearanceOpen.value = false
  if (restore) void nextTick(() => appearanceButton.value?.focus())
}
function outsideAppearance(event: PointerEvent) {
  if (appearanceOpen.value && !appearanceContainer.value?.contains(event.target as Node)) closeAppearance()
}
document.addEventListener('pointerdown', outsideAppearance)
onUnmounted(() => document.removeEventListener('pointerdown', outsideAppearance))
function radioKeydown(event: KeyboardEvent) {
  const direction = ['ArrowRight', 'ArrowDown'].includes(event.key) ? 1 : ['ArrowLeft', 'ArrowUp'].includes(event.key) ? -1 : 0
  if (!direction) return
  const buttons = [...(event.currentTarget as HTMLElement).querySelectorAll<HTMLButtonElement>('[role="radio"]')]
  const current = buttons.indexOf(document.activeElement as HTMLButtonElement)
  if (current < 0 || !buttons.length) return
  event.preventDefault()
  buttons[(current + direction + buttons.length) % buttons.length]?.focus()
}
function changeChord(value?: InspectorValue) {
  const score = currentScore()
  if (!score) return
  const ref = { section: props.section, path: ['TYPE_NOTE', 'TYPE_CHORD'], property: 'combineVoice' }
  const changes = value === undefined ? inspectorPropertyResets(score, ref) : inspectorPropertyChanges(score, ref, value)
  if (applyInspectorChanges(score, changes)) scoreChanged()
}
function change(property: string, value?: InspectorValue) {
  const score = currentScore()
  if (!score) return
  const ref = { section: props.section, path: props.path, property }
  const changes = value === undefined ? inspectorPropertyResets(score, ref) : inspectorPropertyChanges(score, ref, value)
  if (applyInspectorChanges(score, changes)) scoreChanged()
}
async function changeCourtesy(event: Event) {
  const input = event.target as HTMLInputElement
  change('hasToShowCourtesy', input.checked)
  await nextTick()
  input.checked = props.model.properties.hasToShowCourtesy?.value === true
}
function label(name: string, property?: InspectorModelInfo['properties'][string]): string { return property?.label ?? name.replace(/^is(?=[A-Z])/, '').replace(/([a-z])([A-Z])/g, '$1 $2') }
function commitEndings(value: string) {
  if (!/^\s*\d+(?:\s*,\s*\d+)*\s*$/.test(value)) return invalidEndings()
  const numbers = value.split(',').map(token => Number(token.trim()))
  if (numbers.every(n => Number.isSafeInteger(n) && n > 0)) change('endings', numbers)
  else invalidEndings()
}
function invalidEndings() {
  const input = document.activeElement
  if (!(input instanceof HTMLInputElement)) return
  input.setCustomValidity(qtrc('inspector', 'Enter positive measure numbers separated by commas'))
  input.reportValidity()
}
function colorValue(value: InspectorValue | null): string {
  if (typeof value !== 'string') return '#000000'
  return value.length === 9 && value.startsWith('#') ? `#${value.slice(3)}` : value || '#000000'
}
function visibleProperties() { return Object.entries(props.model.properties).filter(([name, p]) => p.isVisible && !p.hidden && (props.showMoreOnly ? p.showMore : !p.showMore) && !(props.model.sectionType === 'SECTION_TEXT' && ['fontFamily', 'fontStyle', 'fontSize', 'symbolSize', 'symbolScale', 'isSizeSpatiumDependent', 'textScriptAlignment'].includes(name)) && !(props.model.modelType === 'TYPE_HAIRPIN' && props.model.flags.isLineType && ['isNienteCircleVisible', 'allowDiagonal', 'height', 'continuousHeight'].includes(name))) }
function columns() { return props.model.sectionType === 'SECTION_GENERAL' ? 'insp-grid2' : 'insp-column' }
function arrange(command: InspectorArrangeCommand) {
  const score = currentScore()
  if (score && applyInspectorChanges(score, inspectorArrangeChanges(score, command))) scoreChanged()
}
function ornamentParts(value: InspectorValue | null) { return value && typeof value === 'object' && 'step' in value ? value : { step: 0, type: 0 } }
function options(name: string) { return (props.model.flags[name] ?? []) as { text: string; value: number }[] }
function intervalItems(part: 'step' | 'type') {
  const values = options(part === 'step' ? 'intervalStepOptions' : 'intervalTypeOptions')
  return values.filter(option => part !== 'type' || option.value <= 5).map(option => ({ label: option.text, value: option.value }))
}
function generalLabel(name: string): string {
  const labels: Record<string, string> = { isVisible: 'Visible', isSmall: 'Cue size', isAutoPlaceAllowed: 'Auto-place', isPlayable: 'Play' }
  return labels[name] ?? label(name)
}
</script>
<template>
  <div v-if="model.sectionType === 'SECTION_GENERAL'" class="insp-column" :class="{ disabled: model.flags.areGeneralPropertiesAvailable === false }">
    <div class="insp-grid2">
      <label v-for="name in ['isVisible', 'isSmall', 'isAutoPlaceAllowed', 'isPlayable']" :key="name" class="insp-checkbox" :data-property="name" :class="{ disabled: !model.properties[name]?.isEnabled }">
        <input type="checkbox" :checked="model.properties[name]?.value === true" :disabled="!model.properties[name]?.isEnabled" @change="change(name, ($event.target as HTMLInputElement).checked)" />
        <span>{{ qtrc('inspector', generalLabel(name)) }}</span>
      </label>
    </div>
    <div class="insp-grid2">
      <button class="insp-flat-button" disabled><span class="insp-button-icon" aria-hidden="true">{{ String.fromCodePoint(ICON_CODES.AUDIO) }}</span>{{ qtrc('inspector', 'Playback') }}</button>
      <div ref="appearanceContainer" class="insp-popup-button" @keydown.esc.stop="closeAppearance(true)">
        <button ref="appearanceButton" class="insp-flat-button" :disabled="!model.models[0] || model.models[0].isEmpty" :aria-expanded="appearanceOpen" aria-haspopup="dialog" @click="appearanceOpen = !appearanceOpen"><span class="insp-button-icon" aria-hidden="true">{{ String.fromCodePoint(ICON_CODES.POSITION_ARROWS) }}</span>{{ qtrc('inspector', 'Appearance') }}</button>
        <div v-if="appearanceOpen && model.models[0]" class="insp-popup" role="dialog" :aria-label="qtrc('inspector', 'Appearance')"><InspectorModel :model="model.models[0]" :section="section" :path="[model.models[0].key]" /></div>
      </div>
    </div>
  </div>
  <div v-else-if="model.key === 'appearance'" class="insp-column">
    <div class="insp-row">
      <div v-for="entry in [{ key: 'leadingSpace', title: 'Leading space', unit: 'sp' }, { key: 'measureWidth', title: 'Measure width', unit: '%' }]" :key="entry.key" class="insp-property">
        <template v-if="model.properties[entry.key]?.isVisible"><div class="insp-property-title"><label :for="`appearance-${entry.key}`">{{ qtrc('inspector', entry.title) }}</label><button class="insp-reset" :disabled="!model.properties[entry.key].isModified || !model.properties[entry.key].isEnabled" :aria-label="qtrc('inspector', 'Reset property to default value')" @click="change(entry.key)">{{ String.fromCodePoint(ICON_CODES.UNDO) }}</button></div><InspectorSpin :id="`appearance-${entry.key}`" :label="qtrc('inspector', entry.title)" :value="model.properties[entry.key].value as number | null" :unit="entry.unit" :step="entry.key === 'measureWidth' ? 5 : 0.5" :min="entry.key === 'measureWidth' ? 0 : -9999" :max="entry.key === 'measureWidth' ? 1000 : 9999" :decimals="entry.key === 'measureWidth' ? 0 : 2" :disabled="!model.properties[entry.key].isEnabled" @commit="value => change(entry.key, value)" /></template>
      </div>
    </div>
    <div class="insp-separator" role="separator" />
    <div v-if="model.properties.minimumDistance?.isVisible" class="insp-property"><div class="insp-property-title"><label for="appearance-distance">{{ qtrc('inspector', 'Minimum distance') }}</label><button class="insp-reset" :disabled="!model.properties.minimumDistance.isModified || !model.properties.minimumDistance.isEnabled" :aria-label="qtrc('inspector', 'Reset property to default value')" @click="change('minimumDistance')">{{ String.fromCodePoint(ICON_CODES.UNDO) }}</button></div><InspectorSpin id="appearance-distance" :label="qtrc('inspector', 'Minimum distance')" :value="model.properties.minimumDistance.value as number | null" :unit="qtrc('global', 'sp')" :disabled="!model.properties.minimumDistance.isEnabled" @commit="value => change('minimumDistance', value)" /></div>
    <div class="insp-separator" role="separator" />
    <div v-if="model.properties.offset?.isVisible && model.properties.offset.value && typeof model.properties.offset.value === 'object' && 'x' in model.properties.offset.value" class="insp-property"><div class="insp-property-title"><span>{{ qtrc('inspector', 'Offset') }}</span><button class="insp-reset" :disabled="!model.properties.offset.isModified || !model.properties.offset.isEnabled" :aria-label="qtrc('inspector', 'Reset property to default value')" @click="change('offset')">{{ String.fromCodePoint(ICON_CODES.UNDO) }}</button></div><div class="insp-row"><InspectorSpin v-for="axis in (model.flags.isVerticalOffsetAvailable === false ? ['x'] : ['x', 'y']) as ('x' | 'y')[]" :key="axis" :label="`${qtrc('inspector', 'Offset')} ${qtrc('inspector', axis === 'x' ? 'Horizontal' : 'Vertical')}`" :value="model.properties.offset.value[axis]" :unit="model.flags.measurementUnits === 'mm' ? qtrc('global', 'mm') : model.flags.measurementUnits === 'sp' || !model.flags.measurementUnits ? qtrc('global', 'sp') : ''" :disabled="!model.properties.offset.isEnabled" @commit="value => change('offset', { ...model.properties.offset.value as object, [axis]: value } as InspectorValue)" /></div></div>
    <div class="insp-separator" role="separator" />
    <div v-if="model.properties.arrangeOrder?.isVisible" class="insp-property"><div class="insp-property-title"><span>{{ qtrc('inspector', 'Arrange') }}</span><button class="insp-reset" :disabled="!model.properties.arrangeOrder.isModified || !model.properties.arrangeOrder.isEnabled" :aria-label="qtrc('inspector', 'Reset property to default value')" @click="change('arrangeOrder')">{{ String.fromCodePoint(ICON_CODES.UNDO) }}</button></div><div class="insp-grid2"><button v-for="entry in [{ label: 'Forwards', command: 'forwards' }, { label: 'To front', command: 'toFront' }, { label: 'Backwards', command: 'backwards' }, { label: 'To back', command: 'toBack' }] as const" :key="entry.command" class="insp-flat-button" :disabled="!model.properties.arrangeOrder.isEnabled" @click="arrange(entry.command)">{{ qtrc('inspector', entry.label) }}</button></div></div>
    <div class="insp-separator" role="separator" />
    <div v-if="model.properties.color?.isVisible" class="insp-property"><div class="insp-property-title"><label for="appearance-color">{{ qtrc('inspector', 'Color') }}</label><button class="insp-reset" :disabled="!model.properties.color.isModified || !model.properties.color.isEnabled" :aria-label="qtrc('inspector', 'Reset property to default value')" @click="change('color')">{{ String.fromCodePoint(ICON_CODES.UNDO) }}</button></div><input id="appearance-color" class="insp-color" type="color" :value="colorValue(model.properties.color.value)" :disabled="!model.properties.color.isEnabled" @change="change('color', ($event.target as HTMLInputElement).value)" /></div>
  </div>
  <div v-else-if="model.modelType === 'TYPE_IMAGE'" class="insp-column">
    <div class="insp-row"><div v-for="entry in [{ key: 'height', title: 'Image height' }, { key: 'width', title: 'Image width' }]" :key="entry.key" v-show="model.properties[entry.key]?.isVisible" class="insp-property"><div class="insp-property-title"><label :for="`image-${entry.key}`">{{ qtrc('inspector', entry.title) }}</label><button class="insp-reset" :disabled="!model.properties[entry.key]?.isModified || !model.properties[entry.key]?.isEnabled" :aria-label="qtrc('inspector', 'Reset property to default value')" @click="change(entry.key)">{{ String.fromCodePoint(ICON_CODES.UNDO) }}</button></div><InspectorSpin :id="`image-${entry.key}`" :label="qtrc('inspector', entry.title)" :value="model.properties[entry.key]?.value as number | null" :unit="model.properties.isSizeInSpatiums?.value === true ? qtrc('global', 'sp') : qtrc('global', 'mm')" :step="0.5" :min="0" :max="9999" :disabled="!model.properties[entry.key]?.isEnabled" @commit="value => change(entry.key, value)" /></div></div>
    <label v-for="entry in [{ key: 'isAspectRatioLocked', title: 'Lock' }, { key: 'shouldScaleToFrameSize', title: 'Scale to frame size' }, { key: 'isSizeInSpatiums', title: 'Use staff space units' }]" :key="entry.key" v-show="model.properties[entry.key]?.isVisible" class="insp-checkbox" :class="{ disabled: !model.properties[entry.key]?.isEnabled }"><input type="checkbox" :checked="model.properties[entry.key]?.value === true" :indeterminate="model.properties[entry.key]?.isUndefined" :disabled="!model.properties[entry.key]?.isEnabled" @change="change(entry.key, ($event.target as HTMLInputElement).checked)" />{{ qtrc('inspector', entry.title) }}</label>
  </div>
  <div v-else-if="model.modelType === 'TYPE_CHORD_BRACKET'" class="insp-column">
    <template v-if="model.flags.isBracket !== false">
      <div v-for="entry in [{ key: 'bracketRightSide', title: 'Placement', choices: [{ text: 'Left', value: false }, { text: 'Right', value: true }] }, { key: 'hookPos', title: 'Hooks', choices: [{ text: 'Both', value: 0 }, { text: 'Above', value: 1 }, { text: 'Below', value: 2 }] }]" :key="entry.key" v-show="model.properties[entry.key]?.isVisible" class="insp-property">
        <div class="insp-property-title"><span>{{ qtrc('inspector', entry.title) }}</span><button class="insp-reset" :disabled="!model.properties[entry.key]?.isModified || !model.properties[entry.key]?.isEnabled" :aria-label="qtrc('inspector', 'Reset property to default value')" @click="change(entry.key)">{{ String.fromCodePoint(ICON_CODES.UNDO) }}</button></div>
        <div class="insp-radio-group" role="radiogroup" :aria-label="qtrc('inspector', entry.title)" @keydown="radioKeydown"><button v-for="choice in entry.choices" :key="String(choice.value)" class="insp-radio" role="radio" :aria-checked="model.properties[entry.key]?.value === choice.value" :disabled="!model.properties[entry.key]?.isEnabled" @click="change(entry.key, choice.value)">{{ qtrc('inspector', choice.text) }}</button></div>
      </div>
      <div v-if="model.properties.hookLen?.isVisible" class="insp-property"><div class="insp-property-title"><label for="bracket-hook-length">{{ qtrc('inspector', 'Hook length') }}</label><button class="insp-reset" :disabled="!model.properties.hookLen.isModified || !model.properties.hookLen.isEnabled" :aria-label="qtrc('inspector', 'Reset property to default value')" @click="change('hookLen')">{{ String.fromCodePoint(ICON_CODES.UNDO) }}</button></div><InspectorSpin id="bracket-hook-length" :label="qtrc('inspector', 'Hook length')" :value="model.properties.hookLen.value as number | null" :unit="qtrc('global', 'sp')" :step="0.1" :min="0" :max="10" :disabled="!model.properties.hookLen.isEnabled" @commit="value => change('hookLen', value)" /></div>
    </template>
  </div>
  <div v-else-if="['TYPE_TEMPO', 'TYPE_A_TEMPO', 'TYPE_TEMPO_PRIMO'].includes(model.modelType)" class="insp-column">
    <label v-if="model.properties.followText?.isVisible" class="insp-checkbox" :data-property="'followText'"><input type="checkbox" :checked="model.properties.followText.value === true" :indeterminate="model.properties.followText.value === null" :disabled="!model.properties.followText.isEnabled" @change="change('followText', ($event.target as HTMLInputElement).checked)" />{{ qtrc('inspector', 'Follow written tempo') }}</label>
    <div v-if="model.properties.followText?.value === false && model.properties.tempo?.isVisible" class="insp-property"><div class="insp-property-title"><label for="tempo-override">{{ qtrc('inspector', 'Override written tempo') }}</label><button class="insp-reset" :disabled="!model.properties.tempo.isModified || !model.properties.tempo.isEnabled" :aria-label="qtrc('inspector', 'Reset property to default value')" @click="change('tempo')">{{ String.fromCodePoint(ICON_CODES.UNDO) }}</button></div><InspectorSpin id="tempo-override" :label="qtrc('inspector', 'Override written tempo')" :value="model.properties.tempo.value as number | null" :unit="qtrc('inspector', 'BPM')" :decimals="1" :step="1" :min="1" :max="999" :disabled="!model.properties.tempo.isEnabled" @commit="value => change('tempo', value)" /></div>
  </div>
  <div v-else-if="model.modelType === 'TYPE_NOTEHEAD' && !showMoreOnly" class="insp-column">
    <div v-for="entry in [{ key: 'hasHeadParentheses', title: 'Notehead parentheses', choices: [{ value: 0, icon: 'NOTE_HEAD', title: 'Normal notehead' }, { value: 3, icon: 'NOTE_HEAD_PARENTHESES', title: 'Notehead with parentheses' }] }]" :key="entry.key" v-show="model.properties[entry.key]?.isVisible && (entry.key !== 'dotPosition' || !model.flags.isTrillCueNote)" class="insp-property">
      <div class="insp-property-title"><span>{{ qtrc('inspector', entry.title) }}</span><button class="insp-reset" :disabled="!model.properties[entry.key]?.isModified || !model.properties[entry.key]?.isEnabled" :aria-label="qtrc('inspector', 'Reset property to default value')" @click="change(entry.key)">{{ String.fromCodePoint(ICON_CODES.UNDO) }}</button></div>
      <div class="insp-radio-group" role="radiogroup" :aria-label="qtrc('inspector', entry.title)" @keydown="radioKeydown"><button v-for="choice in entry.choices" :key="choice.value" class="insp-radio" :class="{ 'insp-icon': choice.icon }" role="radio" :aria-label="qtrc('inspector', choice.title)" :title="qtrc('inspector', choice.title)" :aria-checked="model.properties[entry.key]?.value === choice.value" :disabled="!model.properties[entry.key]?.isEnabled" @click="change(entry.key, choice.value)">{{ choice.icon ? String.fromCodePoint(ICON_CODES[choice.icon]) : qtrc('inspector', 'text' in choice ? String(choice.text) : '') }}</button></div>
    </div>
    <div v-if="model.properties.headGroup?.isVisible" class="insp-property"><div class="insp-property-title"><span>{{ qtrc('inspector', 'Notehead') }}</span><button class="insp-reset" :disabled="!model.properties.headGroup.isModified || !model.properties.headGroup.isEnabled" :aria-label="qtrc('inspector', 'Reset property to default value')" @click="change('headGroup')">{{ String.fromCodePoint(ICON_CODES.UNDO) }}</button></div><select class="insp-dropdown" :value="String(model.properties.headGroup.value)" :disabled="!model.properties.headGroup.isEnabled" @change="change('headGroup', Number(($event.target as HTMLSelectElement).value))"><option v-for="option in options('noteheadGroups')" :key="option.value" :value="option.value">{{ option.text }}</option></select></div>
    <label v-for="entry in [{ key: 'isHeadHidden', text: 'Hide notehead' }, { key: 'isHeadSmall', text: 'Small notehead' }]" :key="entry.key" v-show="model.properties[entry.key]?.isVisible && (entry.key !== 'isHeadHidden' || !model.flags.isTrillCueNote)" class="insp-checkbox" :data-property="entry.key"><input type="checkbox" :checked="model.properties[entry.key]?.value === true" :disabled="!model.properties[entry.key]?.isEnabled" @change="change(entry.key, ($event.target as HTMLInputElement).checked)" />{{ qtrc('inspector', entry.text) }}</label>
    <div v-for="entry in [{ key: 'dotPosition', title: 'Duration dot position', choices: [{ value: 0, text: 'Auto' }, { value: 2, icon: 'DOT_BELOW_LINE' }, { value: 1, icon: 'DOT_ABOVE_LINE' }] }]" :key="entry.key" v-show="model.properties[entry.key]?.isVisible && (entry.key !== 'dotPosition' || !model.flags.isTrillCueNote)" class="insp-property">
      <div class="insp-property-title"><span>{{ qtrc('inspector', entry.title) }}</span><button class="insp-reset" :disabled="!model.properties[entry.key]?.isModified || !model.properties[entry.key]?.isEnabled" :aria-label="qtrc('inspector', 'Reset property to default value')" @click="change(entry.key)">{{ String.fromCodePoint(ICON_CODES.UNDO) }}</button></div>
      <div class="insp-radio-group" role="radiogroup" :aria-label="qtrc('inspector', entry.title)" @keydown="radioKeydown"><button v-for="choice in entry.choices" :key="choice.value" class="insp-radio" :class="{ 'insp-icon': choice.icon }" role="radio" :aria-checked="model.properties[entry.key]?.value === choice.value" :disabled="!model.properties[entry.key]?.isEnabled" @click="change(entry.key, choice.value)">{{ choice.icon ? String.fromCodePoint(ICON_CODES[choice.icon]) : qtrc('inspector', 'text' in choice ? String(choice.text) : '') }}</button></div>
    </div>
    <div v-if="!model.flags.isTrillCueNote" class="insp-showmore">
      <button type="button" class="insp-expand" :aria-expanded="headExpanded" @click="headExpanded = !headExpanded"><span class="insp-arrow" aria-hidden="true">{{ String.fromCodePoint(ICON_CODES.SMALL_ARROW_DOWN) }}</span>{{ qtrc('inspector', headExpanded ? 'Show less' : 'Show more') }}</button>
      <div v-if="headExpanded" class="insp-column">
        <div v-if="model.properties.headSystem?.isVisible" class="insp-property"><div class="insp-property-title"><span>{{ qtrc('inspector', 'Notehead scheme') }}</span><button class="insp-reset" :disabled="!model.properties.headSystem.isModified || !model.properties.headSystem.isEnabled" :aria-label="qtrc('inspector', 'Reset property to default value')" @click="change('headSystem')">{{ String.fromCodePoint(ICON_CODES.UNDO) }}</button></div><select class="insp-dropdown" :aria-label="qtrc('inspector', 'Notehead scheme')" :value="String(model.properties.headSystem.value)" :disabled="!model.properties.headSystem.isEnabled" @change="change('headSystem', Number(($event.target as HTMLSelectElement).value))"><option v-for="option in options('possibleHeadSystemTypes')" :key="option.value" :value="option.value">{{ option.text }}</option></select></div>
