<div v-else-if="['TYPE_SLUR','TYPE_TIE','TYPE_LAISSEZ_VIB','TYPE_PARTIAL_TIE','TYPE_HAMMER_ON_PULL_OFF'].includes(model.modelType)" class="insp-column">
