late></button></div></div>
    <div v-if="model.flags.isMinLengthAvailable && model.properties.minLength?.isVisible" class="insp-property"><div class="insp-property-title"><span>{{ qtrc('inspector','Minimum length') }}</span><button class="insp-reset" :disabled="!model.properties.minLength.isModified || !model.properties.minLength.isEnabled" :aria-label="qtrc('inspector','Reset property to default value')" @click="change('minLength')">{{ String.fromCodePoint(ICON_CODES.UNDO) }}</button></div><InspectorSpin :label="qtrc('inspector','Minimum length')" :value="model.properties.minLength.value as number | null" :min="1" :max="10" :step="0.1" :unit="qtrc('global','sp')" :disabled="!model.properties.minLength.isEnabled" @commit="v => change('minLength',v)" /></div>
