<div v-else-if="model.modelType === 'TYPE_TUPLET'" class="insp-column">
    <div v-for="entry in [{key:'directionType',title:'Direction',items:[{value:0,text:'Auto',icon:''},{value:2,text:'Down',icon:'ARROW_DOWN'},{value:1,text:'Up',icon:'ARROW_UP'}]},{key:'numberType',title:'Number type',items:[{value:0,text:'Number',icon:''},{value:1,text:'Ratio',icon:''},{value:2,text:'None',icon:''}]},{key:'bracketType',title:'Bracket type',items:[{value:0,text:'Auto',icon:''},{value:1,text:'Bracket',icon:'TUPLET_NUMBER_WITH_BRACKETS'},{value:2,text:'None',icon:'TUPLET_NUMBER_ONLY'}]}]" :key="entry.key" v-show="model.properties[entry.key]?.isVisible" class="insp-property"><div class="insp-property-title"><span>{{ qtrc('inspector',entry.title) }}</span><button class="insp-reset" :disabled="!model.properties[entry.key]?.isModified || !model.properties[entry.key]?.isEnabled" :aria-label="qtrc('inspector','Reset property to default value')" @click="change(entry.key)">{{ String.fromCodePoint(ICON_CODES.UNDO) }}</button></div><div class="insp-radio-group" role="radiogroup" :aria-label="qtrc('inspector',entry.title)" @keydown="radioKeydown"><button v-for="item in entry.items" :key="item.value" class="insp-radio" :class="{ 'insp-icon': item.icon }" role="radio" :title="qtrc('inspector',item.text, entry.key === 'directionType' ? 'direction' : entry.key === 'numberType' ? 'tuplet number type' : 'tuplet bracket type')" :aria-label="qtrc('inspector',item.text, entry.key === 'directionType' ? 'direction' : entry.key === 'numberType' ? 'tuplet number type' : 'tuplet bracket type')" :aria-checked="model.properties[entry.key]?.value === item.value" :disabled="!model.properties[entry.key]?.isEnabled" @click="change(entry.key,item.value)"><span v-if="item.icon" class="ms-icon">{{ String.fromCodePoint(ICON_CODES[item.icon as keyof typeof ICON_CODES]) }}</span><template v-else>{{ qtrc('inspector',item.text, entry.key === 'numberType' ? 'tuplet number type' : entry.key === 'bracketType' ? 'tuplet bracket type' : '') }}</template></button></div></div>
    <div v-if="model.properties.lineThickness?.isVisible" class="insp-property"><div class="insp-property-title"><span>{{ qtrc('inspector','Line thickness') }}</span><button class="insp-reset" :disabled="!model.properties.lineThickness.isModified || !model.properties.lineThickness.isEnabled" :aria-label="qtrc('inspector','Reset property to default value')" @click="change('lineThickness')">{{ String.fromCodePoint(ICON_CODES.UNDO) }}</button></div><InspectorSpin :label="qtrc('inspector','Line thickness')" :value="model.properties.lineThickness.value as number | null" :min="0.1" :max="1" :step="0.1" :unit="qtrc('global','sp')" :disabled="!model.properties.lineThickness.isEnabled" @commit="v => change('lineThickness',v)" /></div>
