    <label v-if="model.properties.isSmall?.isVisible" class="insp-checkbox"><input type="checkbox" :checked="model.properties.isSmall.value === true" :disabled="!model.properties.isSmall.isEnabled" @change="change('isSmall', ($event.target as HTMLInputElement).checked)" /><span>{{ qtrc('inspector','Small accidental') }}</span></label>
    <div v-if="model.properties.stackingOrderOffset?.isVisible" class="insp-property"><div class="insp-property-title"><span>{{ label('stackingOrderOffset') }}</span></div><InspectorSpin :label="label('stackingOrderOffset')" :value="model.properties.stackingOrderOffset.value as number | null" :disabled="!model.properties.stackingOrderOffset.isEnabled" @commit="v => change('stackingOrderOffset',v)" /></div>
