<div v-else-if="model.modelType === 'TYPE_FERMATA'" class="insp-column"><div v-if="model.properties.placementType?.isVisible" class="insp-property"><div class="insp-property-title"><span>{{ qtrc('inspector','Position') }}</span><button class="insp-reset" :disabled="!model.properties.placementType.isModified || !model.properties.placementType.isEnabled" :aria-label="qtrc('inspector','Reset property to default value')" @click="change('placementType')">{{ String.fromCodePoint(ICON_CODES.UNDO) }}</button></div><div class="insp-radio-group" role="radiogroup" :aria-label="qtrc('inspector','Position')" @keydown="radioKeydown"><button v-for="item in [{value:0,title:'Above'},{value:1,title:'Below'}]" :key="item.value" class="insp-radio" role="radio" :aria-checked="model.properties.placementType.value === item.value" :disabled="!model.properties.placementType.isEnabled" @click="change('placementType',item.value)">{{ qtrc('inspector',item.title) }}</button></div></div></div>
